INSERT INTO materials (category, brand, model, variant, size, disciplines, construction, year_from, year_to, year_approximate, length_cm, width_cm, height_cm, volume_l, weight_kg, cockpit_length_cm, cockpit_width_cm, paddler_weight_min_kg, paddler_weight_max_kg, product_url, colors, sources, notes, editor_note, blade_area_cm2, blade_length_cm, blade_width_cm, length_min_cm, length_max_cm, lengths_cm, pieces, shaft, shaft_material, blade_material, feather_deg, shaft_diameter, created_by)
SELECT category, brand, model, variant, size, disciplines, construction, year_from, year_to, year_approximate, length_cm, width_cm, height_cm, volume_l, weight_kg, cockpit_length_cm, cockpit_width_cm, paddler_weight_min_kg, paddler_weight_max_kg, product_url, colors, sources, notes, editor_note, blade_area_cm2, blade_length_cm, blade_width_cm, length_min_cm, length_max_cm, lengths_cm, pieces, shaft, shaft_material, blade_material, feather_deg, shaft_diameter, 'system-catalogue' FROM seed_catalogue
ON CONFLICT (category, lower(btrim(brand)), lower(btrim(model)), lower(btrim(COALESCE(variant, ''))), lower(btrim(COALESCE(size, '')))) DO UPDATE SET
    disciplines = EXCLUDED.disciplines,
    construction = EXCLUDED.construction,
    year_from = EXCLUDED.year_from,
    year_to = EXCLUDED.year_to,
    year_approximate = EXCLUDED.year_approximate,
    length_cm = EXCLUDED.length_cm,
    width_cm = EXCLUDED.width_cm,
    height_cm = EXCLUDED.height_cm,
    volume_l = EXCLUDED.volume_l,
    weight_kg = EXCLUDED.weight_kg,
    cockpit_length_cm = EXCLUDED.cockpit_length_cm,
    cockpit_width_cm = EXCLUDED.cockpit_width_cm,
    paddler_weight_min_kg = EXCLUDED.paddler_weight_min_kg,
    paddler_weight_max_kg = EXCLUDED.paddler_weight_max_kg,
    product_url = EXCLUDED.product_url,
    colors = EXCLUDED.colors,
    sources = EXCLUDED.sources,
    notes = EXCLUDED.notes,
    editor_note = EXCLUDED.editor_note,
    blade_area_cm2 = EXCLUDED.blade_area_cm2,
    blade_length_cm = EXCLUDED.blade_length_cm,
    blade_width_cm = EXCLUDED.blade_width_cm,
    length_min_cm = EXCLUDED.length_min_cm,
    length_max_cm = EXCLUDED.length_max_cm,
    lengths_cm = EXCLUDED.lengths_cm,
    pieces = EXCLUDED.pieces,
    shaft = EXCLUDED.shaft,
    shaft_material = EXCLUDED.shaft_material,
    blade_material = EXCLUDED.blade_material,
    feather_deg = EXCLUDED.feather_deg,
    shaft_diameter = EXCLUDED.shaft_diameter,
    updated_at = NOW()
WHERE materials.created_by = 'system-catalogue'
  AND materials.updated_by IS NULL
  AND (materials.category, materials.brand, materials.model, materials.variant, materials.size, materials.disciplines, materials.construction, materials.year_from, materials.year_to, materials.year_approximate, materials.length_cm, materials.width_cm, materials.height_cm, materials.volume_l, materials.weight_kg, materials.cockpit_length_cm, materials.cockpit_width_cm, materials.paddler_weight_min_kg, materials.paddler_weight_max_kg, materials.product_url, materials.colors, materials.sources, materials.notes, materials.editor_note, materials.blade_area_cm2, materials.blade_length_cm, materials.blade_width_cm, materials.length_min_cm, materials.length_max_cm, materials.lengths_cm, materials.pieces, materials.shaft, materials.shaft_material, materials.blade_material, materials.feather_deg, materials.shaft_diameter) IS DISTINCT FROM (EXCLUDED.category, EXCLUDED.brand, EXCLUDED.model, EXCLUDED.variant, EXCLUDED.size, EXCLUDED.disciplines, EXCLUDED.construction, EXCLUDED.year_from, EXCLUDED.year_to, EXCLUDED.year_approximate, EXCLUDED.length_cm, EXCLUDED.width_cm, EXCLUDED.height_cm, EXCLUDED.volume_l, EXCLUDED.weight_kg, EXCLUDED.cockpit_length_cm, EXCLUDED.cockpit_width_cm, EXCLUDED.paddler_weight_min_kg, EXCLUDED.paddler_weight_max_kg, EXCLUDED.product_url, EXCLUDED.colors, EXCLUDED.sources, EXCLUDED.notes, EXCLUDED.editor_note, EXCLUDED.blade_area_cm2, EXCLUDED.blade_length_cm, EXCLUDED.blade_width_cm, EXCLUDED.length_min_cm, EXCLUDED.length_max_cm, EXCLUDED.lengths_cm, EXCLUDED.pieces, EXCLUDED.shaft, EXCLUDED.shaft_material, EXCLUDED.blade_material, EXCLUDED.feather_deg, EXCLUDED.shaft_diameter);

INSERT INTO material_images (material_id, source_url, host, page_url, credit, source_kind)
SELECT m.id, i->>'url', lower(substring(i->>'url' from '^https://([^/?#:@]+)')),
       i->>'page_url', i->>'credit', i->>'kind'
FROM seed_catalogue s
CROSS JOIN LATERAL jsonb_array_elements(s.images) AS i
JOIN materials m ON m.category = s.category
    AND lower(btrim(m.brand)) = lower(btrim(s.brand))
    AND lower(btrim(m.model)) = lower(btrim(s.model))
    AND lower(btrim(COALESCE(m.variant, ''))) = lower(btrim(COALESCE(s.variant, '')))
    AND lower(btrim(COALESCE(m.size, ''))) = lower(btrim(COALESCE(s.size, '')))
ON CONFLICT (material_id, source_url) DO NOTHING;

